(()=>{const get=id=>document.getElementById(id),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tab='bookings',records=[],feedback=[],decision=null;
const dialog=document.createElement('dialog');dialog.id='decision-dialog';dialog.innerHTML='<h2 id="decision-heading"></h2><form id="decision-form"><div id="decision-fields"></div><p id="decision-error" role="alert"></p><button class="primary" type="submit">Save decision</button> <button class="secondary" type="button" id="close-decision">Cancel</button></form>';document.body.append(dialog);get('close-decision').onclick=()=>dialog.close();
async function request(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});let d;try{d=await r.json();}catch{throw Error('Could not reach customer records. Please sign in again.');}if(!r.ok)throw Error(d.error||'Could not save.');return d;}
const actions={requested:[['confirmed','Accept request'],['rejected','Reject request']],confirmed:[['completed','Mark completed'],['cancelled','Cancel booking']],rejected:[],completed:[],cancelled:[]};
const panel=window.customerAdmin={active:false,async load(){get('admin-error').textContent='';try{if(tab==='bookings')records=(await request('/api/admin/bookings')).bookings;else feedback=(await request('/api/admin/feedback')).feedback;panel.render();}catch(e){get('admin-error').textContent=e.message;}},render(){if(dialog.open)return;get('add-button').hidden=true;get('page-title').textContent=tab==='bookings'?'Bookings & customers.':'Reviews & feedback.';get('page-subtitle').textContent=tab==='bookings'?'Accept or reject requests, manage rentals and review private documents.':'Publish approved reviews and read private customer feedback.';get('fleet-search').placeholder='Search by name, phone or message';get('save-info').textContent='Each listing is one car. Accepted bookings block its dates until the return date.';document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('selected'));document.querySelectorAll('[data-customer-view]').forEach(b=>b.classList.toggle('selected',b.dataset.customerView===tab));const term=get('fleet-search').value.toLowerCase();const list=(tab==='bookings'?records:feedback).filter(r=>JSON.stringify(r).toLowerCase().includes(term));get('owner-content').innerHTML=list.length?list.map(r=>tab==='bookings'?`<article class="account-card"><div class="booking-top"><h2>${escape(r.name)}</h2><span class="booking-status">${r.status==='confirmed'?'Accepted':escape(r.status)}</span></div><div class="booking-details"><span>Age ${r.age}<br><a href="tel:${escape(r.phone.replace(/[^+0-9]/g,''))}">${escape(r.phone)}</a><br>${escape(r.email)}</span><span>${escape(r.car_name)} · ${escape(r.location)}<br>${r.mode==='self'?'Self-drive':'Chauffeur'}<br>${escape(r.start_date)} to ${escape(r.end_date)}</span><span>Requested ${escape(new Date(r.created_at).toLocaleString())}<br>Reference ${escape(r.id.slice(0,8))}</span></div>${r.quoted_total==null?'':`<p><strong>Agreed rental total: ₹${r.quoted_total.toLocaleString('en-IN')}</strong></p>`}${r.decision_note?`<p class="private-note">Customer-visible note: ${escape(r.decision_note)}</p>`:''}<div class="decision-actions">${(actions[r.status]||[]).map(([status,label])=>`<button class="${status==='confirmed'?'primary':'secondary'}" data-decide="${escape(r.id)}" data-next-status="${status}">${label}</button>`).join('')}</div>${r.documents.length?r.documents.map(d=>`<div class="document-row"><strong>${d.kind==='licence'?'Driving licence':'Masked Aadhaar'}</strong><a href="/api/admin/documents/${escape(d.id)}" target="_blank" rel="noopener">View private image</a><button class="secondary" data-delete-document="${escape(d.id)}">Delete image</button></div>`).join(''):'<p>No identity images uploaded.</p>'}</article>`:`<article class="account-card"><div class="booking-top"><h2>${r.kind==='review'?'Review · '+escape(r.display_name):'Private feedback'}</h2><span class="booking-status">${escape(r.status)}</span></div><p>${r.kind==='review'?'★'.repeat(r.rating)+' · ':''}${escape(r.email)} · ${escape(new Date(r.created_at).toLocaleString())}</p><p style="white-space:pre-wrap">${escape(r.message)}</p><label>${r.kind==='review'?'Review visibility':'Feedback status'}<select data-feedback-status="${escape(r.id)}">${(r.kind==='review'?['pending','approved','hidden']:['pending','resolved']).map(s=>`<option ${s===r.status?'selected':''} ${r.kind==='review'&&s==='pending'?'disabled':''}>${s}</option>`).join('')}</select></label>${r.kind==='review'?'<p>Only approved reviews are public. Check for personal data before approving.</p>':'<p>This message stays private.</p>'}</article>`).join(''):'<div class="admin-empty">'+(term?'No matching records.':tab==='bookings'?'No booking requests yet.':'No reviews or feedback yet.')+'</div>';}};
document.querySelectorAll('[data-customer-view]').forEach(b=>b.onclick=()=>{panel.active=true;tab=b.dataset.customerView;get('fleet-search').value='';get('owner-content').textContent='Loading customer records…';panel.load();});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('[data-customer-view]').forEach(x=>x.classList.remove('selected'))));
get('refresh').addEventListener('click',()=>{if(panel.active)panel.load();loadNotices();});
get('owner-content').addEventListener('change',async e=>{const id=e.target.dataset.feedbackStatus;if(!id)return;e.target.disabled=true;try{await request('/api/admin/feedback/'+id,{method:'PUT',body:JSON.stringify({status:e.target.value})});await panel.load();}catch(err){get('admin-error').textContent=err.message;e.target.disabled=false;}});
get('owner-content').addEventListener('click',async e=>{const decide=e.target.closest('[data-decide]');if(decide){const booking=records.find(r=>r.id===decide.dataset.decide);decision={booking,status:decide.dataset.nextStatus};const required=['rejected','cancelled'].includes(decision.status);get('decision-heading').textContent=decide.textContent;get('decision-fields').innerHTML=`<p>${escape(booking.car_name)} · ${escape(booking.start_date)} to ${escape(booking.end_date)}</p>${decision.status==='confirmed'?'<label>Agreed rental total · ₹<input type="number" name="quotedTotal" min="0" max="10000000" step="1" required></label><p>Confirm the total and terms with the customer first. Acceptance blocks overlapping bookings for this car. Payment is not collected here.</p>':''}<label>${required?'Reason (shown to customer)':'Note to customer (optional)'}<textarea name="note" maxlength="1000" ${required?'required':''} rows="3"></textarea></label>`;get('decision-error').textContent='';dialog.showModal();return;}const button=e.target.closest('[data-delete-document]');if(!button||!confirm('Permanently delete this identity image?'))return;try{await request('/api/admin/documents/'+button.dataset.deleteDocument,{method:'DELETE'});await panel.load();}catch(err){get('admin-error').textContent=err.message;}});
get('decision-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const v=Object.fromEntries(new FormData(e.target));await request('/api/admin/bookings/'+decision.booking.id,{method:'PUT',body:JSON.stringify({status:decision.status,version:decision.booking.version,note:v.note,quotedTotal:v.quotedTotal==null?undefined:Number(v.quotedTotal)})});dialog.close();await panel.load();await loadNotices();}catch(err){get('decision-error').textContent=err.message;}finally{button.disabled=false;}};
const deliveryLabel={none:'In-app only',not_requested:'In-app only',pending:'Waiting',sending:'Submitting',submitted:'Submitted to provider (delivery unconfirmed)',unconfigured:'Messaging not connected',failed:'Provider rejected message',unknown:'Unknown: check provider logs before retrying'};
async function loadNotices(){if(document.hidden)return;try{const {notifications,messaging}=await request('/api/admin/notifications');get('messaging-status').textContent=(messaging.sms||messaging.whatsapp)?'Connected: '+[messaging.sms?'SMS':'',messaging.whatsapp?'WhatsApp':''].filter(Boolean).join(' & ')+'. Phone delivery is tracked separately from bookings.':'WhatsApp/SMS is not connected yet. In-app alerts are active and refresh every 20 seconds while this panel is open.';get('owner-notifications').innerHTML=notifications.length?notifications.map(n=>`<div class="notice ${n.recipient==='owner'&&!n.read_at?'notice-unread':''}"><p>${escape(n.message)}</p><small>${escape(new Date(n.created_at).toLocaleString())} · ${escape(deliveryLabel[n.channel==='none'?'none':n.delivery_status]||n.delivery_status)}</small>${n.delivery_error&&n.channel!=='none'?`<p>${escape(n.delivery_error)}</p>`:''}${n.recipient==='owner'&&!n.read_at?`<button class="secondary" data-read-notice="${escape(n.id)}">Mark read</button>`:''}${['failed','unconfigured'].includes(n.delivery_status)&&n.channel!=='none'?`<button class="secondary" data-retry-notice="${escape(n.id)}">Retry phone alert</button>`:''}</div>`).join(''):'<p>No booking alerts yet.</p>';if(panel.active&&!dialog.open&&!get('owner-content').contains(document.activeElement))await panel.load();}catch(e){get('messaging-status').textContent=e.message;}}
get('owner-notifications').onclick=async e=>{const read=e.target.closest('[data-read-notice]'),retry=e.target.closest('[data-retry-notice]');if(!read&&!retry)return;try{if(read)await request('/api/admin/notifications/'+encodeURIComponent(read.dataset.readNotice),{method:'PUT',body:'{}'});if(retry)await request('/api/admin/notifications/retry',{method:'POST',body:JSON.stringify({id:retry.dataset.retryNotice})});await loadNotices();}catch(err){get('admin-error').textContent=err.message;}};
loadNotices();setInterval(loadNotices,20000);window.addEventListener('focus',loadNotices);
})();
